"use client";

import { useEffect, useMemo, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { useRouter } from "next/navigation";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import MobileBottomNav from "@/components/MobileBottomNav";

import {
  Phone,
  PhoneCall,
  Volume2,
  AlertTriangle,
  ShieldAlert,
  Ban,
  CheckCircle2,
  Clock,
  User,
  Boxes,
  Loader2,
  RotateCcw,
  ShieldCheck,
  Radio,
  FileText,
  Flame,
  Sparkles,
} from "lucide-react";

type Product = {
  id: string;
  seller_id: string;
  title: string;
  category: string;
  material: string;
  description: string | null;
  specifications: string | null;
  quantity: number;
  quantity_unit: string;
  price: number;
  is_negotiable: boolean;
  condition: string;
  status: string;
  created_at: string;
  ai_review_bucket?: "normal" | "review" | "likely_scam" | string;
  ai_risk_score?: number | null;
  ai_risk_reasons?: string[] | null;
};

type ProductImage = {
  id: string;
  product_id: string;
  image_url: string;
  verification_status: string;
};

type DealCallLog = {
  id: string;
  deal_id: string;
  caller_id: string;
  receiver_id: string;
  duration_seconds: number;
  recording_url: string | null;
  status: string;
  created_at: string;
  transcript?: string | null;
  is_diverted?: boolean | null;
  diverted_party?: string | null;
  diversion_reason?: string | null;
  diversion_snippet?: string | null;
  risk_score?: number | null;
  risk_level?: string | null;
  admin_action?: string | null;
  call_type?: "handover" | "marketplace" | "chat" | "general" | string;
  deal?: {
    deal_code: string;
    agreed_price: number;
    status: string;
    product?: {
      title: string;
      category: string;
    };
  };
  caller?: {
    id: string;
    full_name: string | null;
    warning_count?: number;
    is_banned?: boolean;
    verification_status?: string;
  };
  receiver?: {
    id: string;
    full_name: string | null;
    warning_count?: number;
    is_banned?: boolean;
    verification_status?: string;
  };
};

export default function AdminPage() {
  const supabase = createClient();
  const router = useRouter();

  const [activeTab, setActiveTab] = useState<"products" | "calls">("products");
  const [products, setProducts] = useState<Product[]>([]);
  const [callLogs, setCallLogs] = useState<DealCallLog[]>([]);
  const [callsLoading, setCallsLoading] = useState(false);
  const [callActionLoading, setCallActionLoading] = useState<string | null>(null);

  const [images, setImages] = useState<
    Record<string, ProductImage[]>
  >({});

  const [loading, setLoading] = useState(true);

  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState<
    "success" | "error" | "info"
  >("info");

  const [processingId, setProcessingId] =
    useState<string | null>(null);

  const [selectedImage, setSelectedImage] =
    useState<string | null>(null);

  const [riskFilter, setRiskFilter] = useState<"all" | "normal" | "review" | "likely_scam">("all");
  const [callFilter, setCallFilter] = useState<"all" | "diverted" | "clean">("all");
