async function checkAdminAndLoad() {
  setLoading(true);

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser();

  // Not logged in
  if (userError || !user) {
    router.replace("/login");
    return;
  }

  // Check role from profiles
  const { data: profile, error: profileError } = await supabase
    .from("profiles")
    .select("role")
    .eq("id", user.id)
    .single();

  if (profileError || !profile) {
    console.error("Profile error:", profileError);
    router.replace("/marketplace");
    return;
  }

  // Block buyer/seller
  if (profile.role !== "admin") {
    alert("Access denied. Admin only.");
    router.replace("/marketplace");
    return;
  }

  // Admin verified
  await loadPendingProducts();
}
  const totalImages = useMemo(() => {
    return Object.values(images).reduce(
      (total, productImages) =>
        total + productImages.length,
      0
    );
  }, [images]);

  const riskCounts = useMemo(() => ({
    normal: products.filter((p) => (p.ai_review_bucket || "normal") === "normal").length,
    review: products.filter((p) => p.ai_review_bucket === "review").length,
    likely_scam: products.filter((p) => p.ai_review_bucket === "likely_scam").length,
  }), [products]);

  const filteredProducts = useMemo(() => {
    if (riskFilter === "all") return products;
    return products.filter((p) => (p.ai_review_bucket || "normal") === riskFilter);
  }, [products, riskFilter]);

  async function loadPendingProducts() {
    setLoading(true);
    setMessage("");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      router.push("/login");
      return;
    }

    const { data, error } = await supabase
      .from("products")
      .select("*")
      .eq("status", "pending")
      .order("created_at", {
        ascending: false,
      });

    if (error) {
      console.error(
        "ADMIN PRODUCT LOAD ERROR:",
        error
      );

      setMessage(
        `Products load failed: ${error.message}`
      );

      setMessageType("error");
      setLoading(false);
      return;
    }

    const pendingProducts =
      (data || []) as Product[];

    setProducts(pendingProducts);

    if (pendingProducts.length === 0) {
      setImages({});
      setLoading(false);
      return;
    }

    const productIds =
      pendingProducts.map(
        (product) => product.id
      );

    const {
      data: imageData,
      error: imageError,
    } = await supabase
      .from("product_images")
      .select("*")
      .in("product_id", productIds);

    if (imageError) {
      console.error(
        "ADMIN IMAGE LOAD ERROR:",
        imageError
      );

      setMessage(
        `Products loaded, but images failed to load: ${imageError.message}`
      );

      setMessageType("error");
      setImages({});
    } else {
      const groupedImages: Record<
        string,
        ProductImage[]
      > = {};

      (
        (imageData || []) as ProductImage[]
      ).forEach((image) => {
        if (
          !groupedImages[
            image.product_id
          ]
        ) {
          groupedImages[
            image.product_id
          ] = [];
        }

        groupedImages[
          image.product_id
        ].push(image);
      });

      setImages(groupedImages);
    }

    setLoading(false);
  }

  async function loadCallLogs() {
    setCallsLoading(true);
    try {
      // 1. Fetch from deal_call_logs
      const dealLogsPromise = supabase
        .from("deal_call_logs")
        .select(`
          *,
          caller:caller_id(id, full_name, warning_count, is_banned, verification_status),
          receiver:receiver_id(id, full_name, warning_count, is_banned, verification_status),
          deal:deal_id(
            deal_code, agreed_price, status,
            product:product_id(title, category)
          )
        `)
        .order("created_at", { ascending: false });

      // 2. Also fetch platform-wide calls from 'calls' table
      const platformCallsPromise = supabase
        .from("calls")
        .select(`
          *,
          caller:caller_id(id, full_name, warning_count, is_banned, verification_status),
          receiver:receiver_id(id, full_name, warning_count, is_banned, verification_status),
          deal:deal_id(
            deal_code, agreed_price, status,
            product:product_id(title, category)
          ),
          product:product_id(title, category)
        `)
        .order("created_at", { ascending: false });

      const [dealLogsRes, platformCallsRes] = await Promise.all([dealLogsPromise, platformCallsPromise]);

      const unifiedLogs: DealCallLog[] = [];

      // Add deal_call_logs
      if (dealLogsRes.data && Array.isArray(dealLogsRes.data)) {
        unifiedLogs.push(...(dealLogsRes.data as any[]));
      }

      // Add platform calls that are not duplicates
      if (platformCallsRes.data && Array.isArray(platformCallsRes.data)) {
        for (const c of platformCallsRes.data) {
          const alreadyExists = unifiedLogs.some((u) => u.id === c.id || (u.deal_id && u.deal_id === c.deal_id && Math.abs(new Date(u.created_at).getTime() - new Date(c.created_at).getTime()) < 10000));
          if (!alreadyExists) {
            unifiedLogs.push({
              id: c.id,
              deal_id: c.deal_id || "general-call",
              caller_id: c.caller_id,
              receiver_id: c.receiver_id,
              duration_seconds: c.duration_seconds || 0,
              recording_url: c.recording_url || null,
              status: c.status || "completed",
              created_at: c.created_at,
              transcript: c.transcript || null,
              is_diverted: Boolean(c.is_diverted) || (c.risk_status && c.risk_status !== "LOW"),
              diverted_party: c.diverted_party || null,
              diversion_reason: c.diversion_reason || (c.risk_status === "CRITICAL" ? "High risk off-platform negotiation flagged by AI" : null),
              diversion_snippet: c.diversion_snippet || null,
              risk_score: c.risk_score || (c.risk_status === "CRITICAL" ? 95 : c.risk_status === "HIGH" ? 80 : 10),
              risk_level: c.risk_level || c.risk_status || "LOW",
              deal: c.deal || (c.product ? { deal_code: "DIRECT-CALL", agreed_price: 0, status: "completed", product: c.product } : undefined),
              caller: c.caller,
              receiver: c.receiver,
            });
          }
        }
      }

      // Sort combined logs descending
      unifiedLogs.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
      setCallLogs(unifiedLogs);
    } catch (e) {
      console.warn("Exception loading calls:", e);
    } finally {
      setCallsLoading(false);
    }
  }

  async function handleIssueStrike(userId: string, userName: string, action: "warning" | "ban") {
    const defaultReason =
      action === "warning"
        ? "Attempted off-platform transaction diversion or shared phone number on secure call."
        : "Severe safety violation: Off-platform diversion attempt.";

    const reasonPrompt = window.prompt(
      action === "warning"
        ? `Issue Safety Strike Warning to ${userName}?\nEnter reason:`
        : `Permanently BAN ${userName}?\nEnter reason:`,
      defaultReason
    );
    if (!reasonPrompt) return;

    setCallActionLoading(userId);
    try {
      const { data, error } = await supabase.rpc("admin_issue_warning_or_ban", {
        p_user_id: userId,
        p_action: action,
        p_reason: reasonPrompt,
      });

      if (error || !data?.success) {
        alert(`Action failed: ${error?.message || data?.error || "Error executing action"}`);
      } else {
        if (data.action === "banned") {
          alert(`🚫 User ${userName} has been BANNED (Strike 2 auto-ban or direct ban)!`);
        } else {
          alert(`⚠️ Strike 1 warning issued to ${userName}. (Current warnings: ${data.warnings}/2)`);
        }
        await loadCallLogs();
      }
    } catch (e) {
      alert(`Error: ${(e as Error).message}`);
    } finally {
      setCallActionLoading(null);
    }
  }

