  async function updateProductStatus(
    productId: string,
    status: "approved" | "rejected"
  ) {
    const confirmationMessage =
      status === "approved"
        ? "Approve this product and publish it on the marketplace?"
        : "Reject this product listing?";

    const confirmed =
      window.confirm(
        confirmationMessage
      );

    if (!confirmed) {
      return;
    }

    setProcessingId(productId);

    setMessage(
      status === "approved"
        ? "Approving product..."
        : "Rejecting product..."
    );

    setMessageType("info");

    try {
      // --------------------------------
      // UPDATE PRODUCT
      // --------------------------------

      const {
        error: productError,
      } = await supabase
        .from("products")
        .update({
          status,
        })
        .eq("id", productId);

      if (productError) {
        console.error(
          "PRODUCT STATUS ERROR:",
          productError
        );

        setMessage(
          `Product update failed: ${productError.message}`
        );

        setMessageType("error");
        setProcessingId(null);
        return;
      }

      // --------------------------------
      // UPDATE PRODUCT IMAGES
      // --------------------------------

      const {
        error: imageError,
      } = await supabase
        .from("product_images")
        .update({
          verification_status:
            status,
        })
        .eq(
          "product_id",
          productId
        );

      if (imageError) {
        console.error(
          "IMAGE STATUS ERROR:",
          imageError
        );

        setMessage(
          `Product was ${status}, but image verification could not be updated: ${imageError.message}`
        );

        setMessageType("error");

        await loadPendingProducts();

        setProcessingId(null);
        return;
      }

      setMessage(
        status === "approved"
          ? "✅ Product approved successfully and published to the marketplace."
          : "❌ Product rejected successfully."
      );

      setMessageType("success");

      // Remove immediately from screen
      setProducts((current) =>
        current.filter(
          (product) =>
            product.id !==
            productId
        )
      );

      setImages((current) => {
        const updated = {
          ...current,
        };

        delete updated[
          productId
        ];

        return updated;
      });
    } catch (error) {
      console.error(
        "UNEXPECTED ADMIN ERROR:",
        error
      );

      setMessage(
        `Unexpected error: ${
          error instanceof Error
            ? error.message
            : "Unknown error"
        }`
      );

      setMessageType("error");
    } finally {
      setProcessingId(null);
    }
  }

