      supabase.from("products").select("*").eq("status", "approved").limit(6),
      supabase.from("deal_requests").select("id", { count: "exact" }).eq("buyer_id", user.id),
      supabase.from("product_offers").select("id", { count: "exact" }).eq("buyer_id", user.id),
