              {activeStep >= 3 && (
                <Link
                  href="/marketplace"
                  className="flex items-center gap-2 rounded-xl bg-white px-5 py-2.5 text-xs font-black text-slate-950 shadow-md transition hover:bg-slate-200 hover:scale-105"
