      { label: "Buyer Entity", value: "GreenTech Labs" },
      { label: "Route Transit", value: "12.4 km Route" },
    ],
  },
  {
    id: "exchange",
    number: "04",
    title: "Secure Escrow Exchange",
    tagline: "SAFE PROTOCOL & OTP HANDOVER",
