                  : activeStep === 3
                  ? "radial-gradient(circle, rgba(245, 158, 11, 0.1) 0%, transparent 70%)"
                  : activeStep === 4
                  ? "radial-gradient(circle, rgba(16, 185, 129, 0.12) 0%, transparent 70%)"
