"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import { createClient } from "@/lib/supabase/client";
import {
  Sparkles,
  Layers,
  ShieldCheck,
  Cpu,
  User,
  LogOut,
  Menu,
  X,
  MessageSquare,
  Handshake,
  PlusCircle,
  BarChart3,
  Flame,
  FileText,
} from "lucide-react";

export default function Navbar() {
  const router = useRouter();
  const pathname = usePathname();
  const supabase = useMemo(() => createClient(), []);

  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userId, setUserId] = useState("");
  const [userName, setUserName] = useState<string | null>(null);
  const [isVerified, setIsVerified] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const [messageToast, setMessageToast] = useState<string | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);

  useEffect(() => {
    let mounted = true;

    async function checkUser() {
      try {
        const {
          data: { user },
          error: userError,
        } = await supabase.auth.getUser();

        if (!mounted) return;

        if (userError || !user) {
          setIsLoggedIn(false);
          setUserId("");
          setUserRole(null);
          setUserName(null);
          setIsVerified(false);
          setUnreadCount(0);
          setAuthLoading(false);
          return;
        }

        setIsLoggedIn(true);
        setUserId(user.id);

        const { data: profile } = await supabase
          .from("profiles")
          .select("role, full_name, verification_status")
          .eq("id", user.id)
          .maybeSingle();

        if (!mounted) return;

        setUserRole(profile?.role || null);
        setUserName(profile?.full_name || user.email?.split("@")[0] || "User");
        setIsVerified(profile?.verification_status === "verified");
        const { data: unreadTotal } = await supabase.rpc("get_unread_message_count");
        if (mounted && unreadTotal !== null) {
          setUnreadCount(Number(unreadTotal || 0));
        }
        setAuthLoading(false);
      } catch (error) {
        console.error("Auth check error:", error);
        if (mounted) {
          setIsLoggedIn(false);
          setUserRole(null);
          setAuthLoading(false);
        }
      }
    }

    checkUser();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(() => checkUser());

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [supabase]);

  useEffect(() => {
    if (!userId) return;

    async function refreshUnreadCount() {
      const { data } = await supabase.rpc("get_unread_message_count");
      if (data !== null) setUnreadCount(Number(data || 0));
    }

    refreshUnreadCount();
  }, [pathname, supabase, userId]);

  useEffect(() => {
    if (!userId) return;

    async function refreshUnreadCount() {
      const { data } = await supabase.rpc("get_unread_message_count");
      if (data !== null) setUnreadCount(Number(data || 0));
    }

    const channel = supabase
      .channel(`message-alerts-${userId}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "messages" },
        (payload) => {
          const incoming = payload.new as {
            conversation_id: number;
            sender_id: string;
            message: string;
          };

          if (incoming.sender_id === userId) return;

          setUnreadCount((count) => count + 1);
          setMessageToast(incoming.message);
          window.setTimeout(() => setMessageToast(null), 5000);

          if (typeof Notification !== "undefined" && Notification.permission === "granted") {
            new Notification("New EcoMatch message", {
              body: incoming.message,
              icon: "/favicon.ico",
              tag: `ecomatch-conversation-${incoming.conversation_id}`,
            });
          }
        }
      )
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "messages" },
        () => {
          void refreshUnreadCount();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [supabase, userId]);

  async function handleLogout() {
    setAuthLoading(true);
    await supabase.auth.signOut();
    setIsLoggedIn(false);
    setUserId("");
    setUserRole(null);
    setUnreadCount(0);
    setAuthLoading(false);
